def signature(messages,runner,wire):
    rows,state,message,headers,tag,oids=runner.decode_wire_result(messages,include_types=True)
    return dict(rows=rows,states=[wire.diagnostic_fields(body).get(b'C',b'').decode() for kind,body in messages if kind==b'E'],
        descriptions=[body.hex() for kind,body in messages if kind==b'T'],
        parameters=[body.hex() for kind,body in messages if kind==b't'],
        data=[body.hex() for kind,body in messages if kind==b'D'],
        commands=[body.hex() for kind,body in messages if kind==b'C'],
        frames=[kind.decode() for kind,body in messages],ready=[body.decode() for kind,body in messages if kind==b'Z'])

def execute(sock,sql,mode,wire):
    if mode=='Simple':return wire.simple_query(sock,sql)
    parse=b'\0'+sql.encode()+b'\0'+struct.pack('!H',0)
    bind=b'\0\0'+struct.pack('!HHH',0,0,0)
    sock.sendall(wire.typed(b'P',parse)+wire.typed(b'D',b'S\0')+wire.typed(b'B',bind)+wire.typed(b'D',b'P\0')+
        wire.typed(b'E',b'\0'+struct.pack('!I',0))+wire.typed(b'S'))
    return wire.read_until_ready(sock)

