def main():
    review=Review(LABEL)
    output=Path(os.environ.get("PREPARED_WINDOW_INPUT_KEYS_OUTPUT_DIR") or tempfile.mkdtemp(prefix="dbms-window-input-keys-"))
    output.mkdir(parents=True,exist_ok=True)
    assert len(PLAN)==EXPECTED_CONTROLS
    assert sum(entry['mode']=='Extended' for entry in PLAN)==40
    assert sum(entry['label'].endswith('-Simple') for entry in PLAN)==40
    observations=[];complete=False;created=False
    def save():
        (output/'observations.json').write_text(json.dumps(dict(complete=complete,controls=observations,
            failures=len(review.failures),source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()),indent=2)+'\n')
    try:
        for entry in PLAN:
            messages=execute(review.sock,entry['sql'],entry['mode'],review.client)
            actual=signature(messages,review.runner,review.client)
            if entry['label']=='setup':created=not actual['states']
            valid=actual==entry['expected']
            observations.append(dict(label=entry['label'],sql=entry['sql'],mode=entry['mode'],expected=entry['expected'],
                actual=actual,passed=valid,raw=[[kind.decode(),body.hex()] for kind,body in messages]))
            review.record((entry['label'],entry['mode'],entry['sql']),valid,actual,entry['expected'])
            if len(observations)%25==0:save()
        complete=True
        review.complete(EXPECTED_CONTROLS)
    finally:
        save()
        print(LABEL+"_OBSERVATIONS",str(output/'observations.json'),flush=True)
        try:
            if created:
                cleanup=review.client.simple_query(review.sock,'DROP SEQUENCE key_s')
                assert not any(kind==b'E' for kind,body in cleanup),cleanup
        finally:review.close()

if __name__=='__main__':main()
